// ANTI-PATTERN — may compile with ValidateOnBuild disabled
public sealed class AuditMiddleware
{
    private readonly RequestDelegate _next;
    private readonly AppDbContext _db; // CAPTIVE — one context for app life

    public AuditMiddleware(RequestDelegate next, AppDbContext db)
    {
        _next = next;
        _db = db;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        _db.AuditLogs.Add(new AuditLog { Path = context.Request.Path });
        await _db.SaveChangesAsync();
        await _next(context);
    }
}

public sealed class AuditMiddleware(RequestDelegate next)
{
    public async Task InvokeAsync(HttpContext context, AppDbContext db)
    {
        db.AuditLogs.Add(new AuditLog
        {
            Path = context.Request.Path,
            At = DateTimeOffset.UtcNow
        });
        await db.SaveChangesAsync();
        await next(context);
    }
}

builder.Services.AddDbContext<AppDbContext>();
app.UseMiddleware<AuditMiddleware>();

public sealed class TenantMiddleware(AppDbContext db) : IMiddleware
{
    public async Task InvokeAsync(HttpContext context, RequestDelegate next)
    {
        var tenantId = context.Items["TenantId"] as string;
        db.TenantFilter = tenantId;
        await next(context);
    }
}

builder.Services.AddScoped<TenantMiddleware>();
app.UseMiddleware<TenantMiddleware>();

var builder = WebApplication.CreateBuilder(args);
builder.Host.UseDefaultServiceProvider(options =>
{
    options.ValidateScopes = true;  // default in Development
    options.ValidateOnBuild = true;
});

